import { FormEvent, useState } from 'react';

import queryString from 'query-string';
import { useLocation, useNavigate } from 'react-router-dom';

import { changeUserPassword } from '@apps/Users/@services/user.services';
import PageLoader from '@components/PageLoader';
import { success, warn } from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

function ChangePassword({ code }: { code?: string }) {
  const location = useLocation();
  const navigate = useNavigate();
  const search = queryString.parse(location.search) || {};
  const redirectUrl = search.return || search.rel || '/';
  const prefilingLogin = search.login;

  const [loading, setLoading] = useState(false);
  const [psw1, setPsw1] = useState('');
  const [psw2, setPsw2] = useState('');

  const handleSubmit = async (event: FormEvent) => {
    event.preventDefault();

    if (psw1 !== psw2) {
      return;
    }

    setLoading(true);
    try {
      const result = await changeUserPassword({ code, psw1, psw2 });
      if (result?.success) {
        success('Пароль успешно изменен. Авторизуйтесь');
        navigate(`/login?return=${redirectUrl}&login=${prefilingLogin}`);
      }
    } catch (error) {
      warn((error as Error).message || 'Что-то пошло не так');
    }

    setLoading(false);
  };

  const getMessage = () => {
    if (!psw1 || !psw2) {
      return null;
    }

    if (psw1 !== psw2) {
      return <span className="text-danger">Введенные пароли не совпадают</span>;
    }

    if (psw1 === psw2) {
      return <span className="text-success">Введенные пароли совпадают</span>;
    }

    return null;
  };

  return (
    <PohContainer>
      <PohRow>
        <PohCol sm={{ span: 12 }} md={{ span: 6, offset: 3 }} lg={{ span: 4, offset: 4 }}>
          <h2>Изменение пароля</h2>
          {loading && <PageLoader />}
          {!loading && (
            <form onSubmit={handleSubmit} className="d-flex flex-column" style={{ gap: 12 }}>
              <PohInput onChange={setPsw1} value={psw1} required label="Введите новый пароль" />
              <PohInput
                onChange={setPsw2}
                value={psw2}
                required
                label="Новый пароль еще раз"
                message={getMessage()}
              />
              <PohButton onClick={() => {}} type="submit" variant={ButtonVariant.Primary}>
                Изменить пароль
              </PohButton>
            </form>
          )}
        </PohCol>
      </PohRow>
    </PohContainer>
  );
}

export default ChangePassword;
